{
  "expo": {
    "name": "Type",
    "slug": "typenotes",
    "version": "0.1.0",
    "scheme": [
      "typenotes",
      "type2"
    ],
    "orientation": "portrait",
    "userInterfaceStyle": "automatic",
    "newArchEnabled": true,
    "ios": {
      "bundleIdentifier": "com.typenotes.mobile",
      "buildNumber": "2026070801",
      "supportsTablet": true,
      "infoPlist": {
        "UIFileSharingEnabled": true,
        "LSSupportsOpeningDocumentsInPlace": true,
        "ITSAppUsesNonExemptEncryption": false,
        "NSPhotoLibraryUsageDescription": "Type does not access your photo library; this permission is required by a bundled camera component.",
        "NSPhotoLibraryAddUsageDescription": "Type does not save to your photo library; this permission is required by a bundled camera component.",
        "NSLocalNetworkUsageDescription": "Type connects to your computer over the local network to sync your notes.",
        "NSBonjourServices": [
          "_typenotes-sync._tcp"
        ]
      }
    },
    "android": {
      "package": "com.typenotes.mobile"
    },
    "plugins": [
      [
        "expo-audio",
        {
          "microphonePermission": "Type uses the microphone to record voice notes."
        }
      ],
      [
        "expo-camera",
        {
          "cameraPermission": "Type uses the camera to scan the sync QR code shown by the desktop app."
        }
      ],
      [
        "expo-speech-recognition",
        {
          "microphonePermission": "Type uses the microphone to record voice notes.",
          "speechRecognitionPermission": "Type uses speech recognition to transcribe your voice notes on this device."
        }
      ]
    ]
  }
}

